          }
          case 'gravito.autopilotCycle': {
            result = await safeTool(async () => {
              const creativeService = getCreativePartnerService();
              return { content: [{ type: 'text', text: JSON.stringify(await creativeService.autopilotCycle(unsafeCast(normalizedArgs, "boundary cast"))) }] };
            });
            break;
          }

          // Workflow Wrapper Tools (Enterprise)
          case 'gravito.certifyRelease':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.certifyRelease(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
