});

// ============================================================================
// ROUTER SETUP
// ============================================================================

export const mcpRouter = Router();

// Initialize MCP server on first request
let serverInitialized = false;

function ensureServerInitialized() {
  if (!serverInitialized) {
    initGravitoMCPServer('1.0.0');
    serverInitialized = true;
  }
}

// ============================================================================
// ROOT ENDPOINT - Returns server info (prevents 404 on base URL)
// ============================================================================

mcpRouter.get('/', (req: Request, res: Response) => {
  ensureServerInitialized();
  res.json({
    jsonrpc: '2.0',
    result: {
      protocolVersion: '2024-11-05',
      capabilities: {
        tools: {},
      },
      serverInfo: {
        name: GRAVITO_MCP_SERVER_NAME,
        version: '1.0.0',
      },
    },
  });
});

// ============================================================================
// SSE ENDPOINT - Server-Sent Events for MCP protocol
// ============================================================================

mcpRouter.get('/sse', (req: Request, res: Response) => {
  ensureServerInitialized();

  const origin = req.headers.origin;
  if (typeof origin === 'string' && isAllowedGovernanceCorsOrigin(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  // Set SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  // Send initial connection event with server info
  const serverInfo = {
    jsonrpc: '2.0',
    method: 'notifications/initialized',
    params: {
      protocolVersion: '2024-11-05',
      capabilities: {
        tools: {},
      },
      serverInfo: {
        name: GRAVITO_MCP_SERVER_NAME,
        version: '1.0.0',
      },
    },
  };

  res.write(`data: ${JSON.stringify(serverInfo)}\n\n`);

  // Keep connection alive
  const keepAlive = setInterval(() => {
    res.write(': keepalive\n\n');
  }, 30000);

  req.on('close', () => {
    clearInterval(keepAlive);
  });
});

// ============================================================================
// JSON-RPC ENDPOINT - For MCP protocol messages
// ============================================================================

mcpRouter.post('/', async (req: Request, res: Response) => {
  ensureServerInitialized();
  const server = getGravitoMCPServer();
  const requestStart = Date.now();
  const clientIp = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() || req.ip || '0.0.0.0';
  const apiKey = extractApiKey(req) ?? null;
  const userAgent = req.headers['user-agent'] || '';

  // ================================================================
  // RATE LIMITING — check before processing
  // ================================================================
  const rateResult = checkRateLimit(apiKey, clientIp);
  if (!rateResult.allowed) {
    // Log the rate-limited request
    logUsage({
      apiKey,
      ipAddress: clientIp,
      toolName: 'rate_limited',
      method: req.body?.method || 'unknown',
      success: false,
      errorMessage: rateResult.reason,
      responseTimeMs: Date.now() - requestStart,
      userAgent,
    });

    res.setHeader('X-RateLimit-Remaining-Minute', String(rateResult.remaining.minute));
    res.setHeader('X-RateLimit-Remaining-Daily', String(rateResult.remaining.daily));
    res.setHeader('X-RateLimit-Reset-Minute-Ms', String(rateResult.resetIn.minuteMs));
    res.setHeader('Retry-After', String(Math.ceil(rateResult.resetIn.minuteMs / 1000)));

    return res.status(429).json({
      jsonrpc: '2.0',
      id: req.body?.id,
      error: {
        code: -32000,
        message: rateResult.reason,
        data: {
          remaining: rateResult.remaining,
          resetIn: rateResult.resetIn,
        },
      },
    });
  }

  // Consume the request slot
  consumeRequest(apiKey, clientIp);

  // Set rate limit headers on all responses
  res.setHeader('X-RateLimit-Remaining-Minute', String(rateResult.remaining.minute));
  res.setHeader('X-RateLimit-Remaining-Daily', String(rateResult.remaining.daily));

  try {
    const { jsonrpc, id, method, params } = req.body;

    if (jsonrpc !== '2.0') {
      return res.json({
        jsonrpc: '2.0',
        id,
        error: { code: -32600, message: 'Invalid Request - must be JSON-RPC 2.0' },
      });
    }

    let result: any;

    switch (method) {
      case 'initialize':
        result = {
          protocolVersion: '2024-11-05',
          capabilities: {
            tools: {},
          },
          serverInfo: {
            name: GRAVITO_MCP_SERVER_NAME,
            version: '1.0.0',
          },
        };
        break;

      case 'tools/list':
        result = {
          tools: ALL_TOOLS.map(tool => ({
            name: tool.name,
            description: tool.description,
            inputSchema: isZodSchema(tool.inputSchema) ? zodToJsonSchema(tool.inputSchema) : tool.inputSchema,
          })),
        };
        break;

      case 'tools/call': {
        const tcKey = extractApiKey(req);
        const hasServerKey =
          !!process.env.BUILT_IN_FORGE_API_KEY?.trim() ||
          !!process.env.GRAVITO_API_KEY?.trim() ||
          !!process.env.GravitoAPI?.trim();
        if (process.env.NODE_ENV !== 'development' || hasServerKey) {
          if (!tcKey) {
            return res.status(401).json({
              jsonrpc: '2.0',
              id: req.body?.id,
              error: {
                code: -32000,
                message:
                  'Authentication required for tools/call. Use Authorization: Bearer or x-api-key / x-gravito-api-key.',
              },
            });
          }
          if (!(await validateApiKey(tcKey))) {
            return res.status(403).json({
              jsonrpc: '2.0',
              id: req.body?.id,
              error: { code: -32001, message: 'Invalid API key.' },
            });
          }
        }
        const { name, arguments: args } = params || {};
        generalLog.info(`[MCP JSON-RPC] Tool call: ${name}`, JSON.stringify(args).substring(0, 200));

        // ================================================================
        // AUTO SURFACE REGISTRATION
        // Register external product on every MCP tool call (lazy, cached).
        // Uses product_id from args or derives from the request context.
        // ================================================================
        try {
          const { registerSurfaceIfMissing } = await import('../governance/auto-surface-registration');
          const productId = (args as unknown as Record<string, unknown>)?.product_id || (args as unknown as Record<string, unknown>)?.surface_id || req.headers['x-product-id'] as string || 'unknown-mcp-client';
          const productName = (args as unknown as Record<string, unknown>)?.product_name || req.headers['x-product-name'] as string || undefined;
          await registerSurfaceIfMissing({
            productId,
            productName,
            registrationSource: 'mcp_connection',
            registeredBy: req.headers['x-api-key'] ? 'api-key-auth' : 'anonymous',
          });
        } catch (regErr) {
          generalLog.warn(`[MCP] Auto-registration failed (non-blocking): ${regErr}`);
        }

        // ================================================================
        // UNIVERSAL INPUT NORMALIZER
        // The MCP tool schemas use 'artifact' as the primary field name
        // for creative tools, but some server methods expect 'content'.
        // This normalizer ensures both field names work everywhere.
        // ================================================================
        const normalizeInput = (toolName: string | undefined, rawArgs: any): any => {
          if (!rawArgs || typeof rawArgs !== 'object') return rawArgs || {};
          const a = { ...rawArgs };

          // Creative Integrity Engine tools: schema says 'artifact', methods expect 'content'
          const artifactToContentTools = [
            'gravito.clarifyIntent', 'gravito.detectAbstraction',
          ];
          if (artifactToContentTools.includes(toolName || '') && a.artifact && !a.content) {
            a.content = a.artifact;
          }

          // clarifyIntent: schema says 'declared_intent' → method expects 'context'
          if (toolName === 'gravito.clarifyIntent' && a.declared_intent && !a.context) {
            a.context = a.declared_intent;
          }

          // suggestRefinement: schema says 'artifact' + 'mode' → method expects 'content' + 'goal'
          if (toolName === 'gravito.suggestRefinement') {
            if (a.artifact && !a.content) a.content = a.artifact;
            if (a.mode && !a.goal) a.goal = a.mode;
          }

          // checkCoherence: schema says 'artifact' → method expects sections[]
          if (toolName === 'gravito.checkCoherence' && a.artifact && !a.sections && !a.content_blocks) {
            // Split artifact into sections by paragraph
            const paragraphs = a.artifact.split(/\n\n+/).filter((p: string) => p.trim());
            a.sections = paragraphs.map((p: string, i: number) => ({
              title: `Section ${i + 1}`,
              content: p.trim(),
            }));
          }

          // runCreativeIntegrity: schema says 'artifact'+'declared_intent'+'target_audience'
          // method expects 'content'+'intent'+'audience'
          if (toolName === 'gravito.runCreativeIntegrity') {
            if (a.artifact && !a.content) a.content = a.artifact;
            if (a.declared_intent && !a.intent) a.intent = a.declared_intent;
            if (a.target_audience && !a.audience) a.audience = a.target_audience;
            // Provide defaults for required fields
            if (!a.intent) a.intent = 'general communication';
            if (!a.audience) a.audience = 'general audience';
          }

          // generateArtifact: schema (GenerateArtifactInputSchema) expects surface_type, artifact_type, goal, audience, context
          // but server method expects prompt, artifact_type, constraints
          if (toolName === 'gravito.generateArtifact') {
            // Build prompt from available fields
            if (!a.prompt) {
              const parts: string[] = [];
              if (a.goal) parts.push(`Goal: ${a.goal}`);
              if (a.audience) parts.push(`Audience: ${a.audience}`);
              if (a.context) parts.push(`Context: ${a.context}`);
              if (a.artifact) parts.push(a.artifact);
              if (a.content) parts.push(a.content);
              a.prompt = parts.length > 0 ? parts.join('. ') : `Generate a ${a.artifact_type || 'content'} artifact`;
            }
            // Map creative artifact_types to valid review artifact_types
            const creativeToReviewType: Record<string, string> = {
              'hero_section': 'web_copy', 'pricing_copy': 'web_copy', 'landing_page': 'web_copy',
              'onboarding_step': 'web_copy', 'cta': 'web_copy', 'value_prop': 'web_copy',
              'headline': 'web_copy', 'subheadline': 'web_copy',
              'support_macro': 'message', 'ad_copy': 'ad_copy', 'email': 'email',
            };
            if (a.artifact_type && creativeToReviewType[a.artifact_type]) {
              // Store original type in constraints for output, use mapped type for governance review
              a.constraints = { ...(a.constraints || {}), original_artifact_type: a.artifact_type };
              a.artifact_type = creativeToReviewType[a.artifact_type];
            }
          }

          // generateVariants: schema expects surface_type, artifact_type, goal, audience
          // but server method expects base_content, variant_count, variation_type
          if (toolName === 'gravito.generateVariants') {
            if (!a.base_content && a.artifact) a.base_content = a.artifact;
            if (!a.base_content && a.content) a.base_content = a.content;
            if (!a.variant_count && a.num_variants) a.variant_count = a.num_variants;
            if (!a.variant_count) a.variant_count = 3;
            if (!a.variation_type) a.variation_type = a.goal || 'general';
          }

          // ================================================================
          // BRIDGE TOOL NORMALIZATION
          // Messaging/positioning tools expect 'headline', not 'content'
          // ================================================================
          const headlineTools = new Set([
            'gravito.analyzePositioning', 'gravito.analyzeFearUrgency',
            'gravito.checkSafeButForgettable', 'gravito.analyzeGravitas',
            'gravito.checkFeatureStartupLanguage', 'gravito.fullMessagingAnalysis',
            'gravito.analyzeBuyerObjections', 'gravito.analyzeCompetitiveDifferentiation',
            'gravito.checkCriticalObjectionGaps', 'gravito.checkGenericCopy',
            'gravito.comprehensiveGapAnalysis',
          ]);
          if (headlineTools.has(toolName || '')) {
            // Map 'content' or 'artifact' → 'headline' if headline not provided
            if (!a.headline && (a.content || a.artifact)) {
              a.headline = a.content || a.artifact;
            }
            // Provide a default headline from any text field
            if (!a.headline && a.text) {
              a.headline = a.text;
            }
          }

          // checkPersonaResonance: requires targetPersona enum
          if (toolName === 'gravito.checkPersonaResonance') {
            if (!a.targetPersona) a.targetPersona = 'cto'; // sensible default
          }

          // auditArtifactWithGovernance: requires artifactId, artifactName, surfaceType
          if (toolName === 'gravito.auditArtifactWithGovernance') {
            if (!a.artifactId) a.artifactId = `audit-${Date.now()}`;
            if (!a.artifactName) a.artifactName = a.name || 'Untitled Artifact';
            if (!a.surfaceType) a.surfaceType = 'website';
          }

          // createBaseline: requires artifactId, artifactName
          if (toolName === 'gravito.createBaseline') {
            if (!a.artifactId) a.artifactId = `baseline-${Date.now()}`;
            if (!a.artifactName) a.artifactName = a.name || 'Untitled';
          }

          // demoReviewCycle: requires artifactType enum
          if (toolName === 'gravito.demoReviewCycle') {
            if (!a.artifactType) a.artifactType = 'copy'; // sensible default
          }

          // verifyClaim: requires claim_category enum and claim_text
          if (toolName === 'gravito.verifyClaim') {
            if (!a.claim_text && a.claim) a.claim_text = a.claim;
            if (!a.claim_text && a.content) a.claim_text = a.content;
            if (!a.claim_text && a.artifact) a.claim_text = a.artifact;
            if (!a.claim_category) a.claim_category = 'accuracy'; // sensible default
            // Pass context through for contradiction detection
            if (!a.context && a.supporting_context) a.context = a.supporting_context;
            if (!a.context && a.evidence) a.context = a.evidence;
          }

          // checkCriticalAlignment: requires homepageContent + pricingContent
          if (toolName === 'gravito.checkCriticalAlignment') {
            if (!a.homepageContent && a.content) a.homepageContent = a.content;
            if (!a.pricingContent) a.pricingContent = a.homepageContent || a.content || '';
          }

          // Universal fallback: if tool expects 'content' but only 'artifact' or 'text' provided
          if (!a.content && (a.artifact || a.text)) {
            a.content = a.artifact || a.text;
          }

          // Universal fallback: if tool expects 'artifact' but only 'content' provided
          if (!a.artifact && a.content) {
            a.artifact = a.content;
          }

          return a;
        };

        const normalizedArgs = normalizeInput(name, args);

        // ================================================================
        // PRODUCT ENTITLEMENT CHECK — The Circuit Breaker
        // Every tool call must pass through authorizeProductAccess.
        // If the org doesn't have the product, the request is denied.
        // Internal operator tenant bypasses all checks.
        //
        // For master-key requests (the website itself), we resolve the
        // tenant via getDogfoodContext so dogfood mode can simulate
        // customer plans. For provisioned user keys, we resolve the
        // org from the key's association.
        // ================================================================
        let authCtx: AuthorizationContext | null = null;

        if (((req as unknown as Record<string, unknown>)).authMethod === 'master') {
          // Master key — use dogfood context (internal tenant or simulated plan)
          // Owner user ID defaults to 1 for dogfood context resolution
          const dogfoodCtx = await getDogfoodContext(((req as unknown as Record<string, unknown>)).authUserId || 1);
          authCtx = {
            orgId: dogfoodCtx.orgId,
            orgSlug: dogfoodCtx.orgSlug,
            orgPlan: dogfoodCtx.isDogfoodActive ? (dogfoodCtx.simulatedPlan || 'free') : 'internal',
            isInternal: dogfoodCtx.isInternal,
            requestIp: clientIp,
          };
        } else if (apiKey) {
          // Provisioned user key — resolve from key prefix
          authCtx = await resolveAuthContext(
            apiKey.substring(0, 12),
            clientIp
          );
        }

        if (authCtx) {
          const authResult = await authorizeProductAccess(name || '', authCtx);
          if (!authResult.authorized) {
            generalLog.info(`[MCP] Entitlement denied: ${name} for org ${authCtx.orgSlug} — ${authResult.reason}`);
            result = {
              content: [{
                type: 'text',
                text: JSON.stringify({
                  ...mcpError(authResult.reason || 'Entitlement denied', 'PERMISSION_ERROR', name),
                  product_code: authResult.productCode,
                  gravito_run_id: `denied_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
                }),
              }],
            };
            break;
          }
        }

        // ================================================================
        // CUSTOMER-SAFE EXECUTION WRAPPER (containedTool)
        // Replaces safeTool. NO raw error messages EVER reach the customer.
        // On failure: classify → check surface regulation → build structured response.
        // Regulated surfaces fail-closed. Non-regulated degrade gracefully.
        // ================================================================
        const MCP_REQUEST_TIMEOUT_MS = 45_000;

        // Extract surface from tool args for regulatory classification
        const extractSurface = (toolName: string, toolArgs: any): string => {
          return toolArgs?.surface || toolArgs?.surface_id || toolArgs?.product_id || 
                 (toolName.includes('Trading') || toolName.includes('Trade') ? 'financial' : 
                  toolName.includes('Email') || toolName.includes('Outbound') ? 'marketing' : 'general');
        };

        const containedTool = async (fn: () => Promise<any>, toolName: string, toolArgs: any): Promise<any> => {
          const surface = extractSurface(toolName, toolArgs);
          const requestId = `${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;

          // Wrap fn with timeout
          const timedFn = async () => {
            const resultPromise = fn();
            const timeoutPromise = new Promise<never>((_, reject) => {
              setTimeout(
                () => reject(new Error(`Upstream timeout after ${MCP_REQUEST_TIMEOUT_MS}ms`)),
                MCP_REQUEST_TIMEOUT_MS,
              );
            });
            return await Promise.race([resultPromise, timeoutPromise]);
          };

          // Execute with idempotent retry: 3 attempts, 1s/2s/4s backoff
          // Only retries transient errors (503, ECONNREFUSED, timeout)
          // Never retries validation, rate limit, or governance blocks
          const retryResult = await withIdempotentRetry(timedFn, {
            label: toolName,
          });

          if (retryResult.success) {
            if (retryResult.attempts > 1) {
              generalLog.info(`[MCP] Tool ${toolName} succeeded after ${retryResult.attempts} attempts (${retryResult.totalTimeMs}ms total)`);
            }
            return retryResult.result;
          }

          // All retries exhausted — build customer-safe response
          generalLog.error(`[MCP] Tool ${toolName} failed after ${retryResult.attempts} attempts (${retryResult.totalTimeMs}ms): ${retryResult.lastClassification}`);

          // Run internal-only analysis as fallback (if content is available)
          let internalAnalysis: ReturnType<typeof runInternalAnalysis> | undefined;
          const content = toolArgs?.content || toolArgs?.thesis || toolArgs?.artifact || toolArgs?.text;
          if (content && typeof content === 'string') {
            try {
              internalAnalysis = runInternalAnalysis(content, surface);
            } catch (analysisErr) {
              generalLog.warn(`[MCP] Internal analysis also failed:`, analysisErr);
            }
          }

          // Build customer-safe response — NEVER leaks raw error
          const customerResponse = buildCustomerErrorResponse(
            retryResult.lastError,
            surface,
            requestId,
            internalAnalysis,
          );

          return {
            content: [{
              type: 'text',
              text: JSON.stringify(customerResponse),
            }],
