            break;

          // Agent Runtime Pack Tools
          case 'gravito.validateToolCall':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await validateToolCall(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.detectPromptInjection':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await detectPromptInjection(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.enforceEscalation':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await enforceEscalation(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.routeModel':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await routeModel(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;

          // Truth & Evidence Governance Tools
          case 'gravito.classifyClaims':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.classifyClaims(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
