            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.requireEvidence(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.validateTruthSurface':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.validateTruthSurface(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;

          // Creative Integrity Engine Tools (Conduit)
          case 'gravito.clarifyIntent':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.clarifyIntent(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.simulatePerception':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.simulatePerception(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.detectAbstraction':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await server.detectAbstraction(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.checkCoherence':
