mcpRouter.post('/tools/list', (req: Request, res: Response) => {
  ensureServerInitialized();

  // Convert Zod schemas to JSON Schema format for MCP compatibility
  // Finance Pack tools already have JSON schema, others need conversion
  const catalog = resolveToolsForMcpList();
  const tools = catalog.map(tool => {
