              result = { content: [{ type: 'text', text: JSON.stringify(mcpError('Break-glass drill failed', classifyError(e), 'gravito.breakGlassDrill')) }] };
            }
            break;
          }
          case 'gravito.runAutoExpire': {
            const { runAutoExpireJob: expire } = await import('../agent/mcp/break-glass-ops');
            try {
              const expireRes = await expire();
              result = { content: [{ type: 'text', text: JSON.stringify(expireRes) }] };
            } catch (e: unknown) {
              generalLog.error('[MCP] runAutoExpire error:', e);
              result = { content: [{ type: 'text', text: JSON.stringify(mcpError('Auto-expire operation failed', classifyError(e), 'gravito.runAutoExpire')) }] };
            }
            break;
          }
          case 'gravito.runEscalation': {
            const { runEscalationCheck: escalate } = await import('../agent/mcp/break-glass-ops');
            try {
              const escRes = await escalate(readNumberField(args, 'thresholdMinutes') ?? 30);
              result = { content: [{ type: 'text', text: JSON.stringify(escRes) }] };
            } catch (e: unknown) {
              generalLog.error('[MCP] runEscalation error:', e);
              result = { content: [{ type: 'text', text: JSON.stringify(mcpError('Escalation check failed', classifyError(e), 'gravito.runEscalation')) }] };
            }
            break;
          }

          // Enforcement tools
          case 'gravito.enforcementStats':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(getEnforcementStats()) }] }));
            break;
          case 'gravito.enforcementLog':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(getEnforcementLog(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.preReleaseCheck':
            result = await safeTool(async () => ({ content: [{ type: 'text', text: JSON.stringify(await preReleaseGate(unsafeCast(normalizedArgs, "boundary cast"))) }] }));
            break;
          case 'gravito.checkContentEnforcement': {
            result = await safeTool(async () => {
              const checkResult = await duringCreationCheck(normalizedArgs?.content || '', normalizedArgs?.contentType || 'general');
              return { content: [{ type: 'text', text: JSON.stringify(checkResult) }] };
            });
            break;
          }
          case 'gravito.governedGenerate': {
            result = await safeTool(async () => {
              const { governedGenerate } = await import('../governance/governed-generate');
              const prompt = normalizedArgs?.prompt || 'Generate content';
              const contentType = normalizedArgs?.contentType || 'general';
              const systemPrompt = normalizedArgs?.systemPrompt || 'You are a professional content writer. Generate clear, accurate, and compliant content.';
              const productId = normalizedArgs?.product_id || req.headers['x-product-id'] as string || undefined;
              const productName = normalizedArgs?.product_name || req.headers['x-product-name'] as string || undefined;
              const contentRole = normalizedArgs?.content_role || 'user-facing';
              const audienceType = normalizedArgs?.audience_type || 'general';

              // Populate the TRUSTED authenticated tenant ONLY when canonical receipt emission
              // is enabled (CANONICAL_VERDICT_RECEIPT_ENABLED default-OFF ⇒ no resolution runs ⇒
              // byte-identical prod behavior). Source-gated ('inference_auth'); provisioned keys
              // only; spoof-proof (resolveInferenceTenant ignores x-gravito-tenant for tenant keys).
              let authenticatedTenant: { tenantId: string; source: string } | undefined;
              if (isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
                authenticatedTenant = await resolveGovernedAuthenticatedTenant(req);
              }

              const genResult = await governedGenerate({
                messages: [{ role: 'user' as const, content: prompt }],
                systemPrompt,
                contentType,
                contentRole,
                audienceType,
                productId,
                productName,
                surfaceId: normalizedArgs?.surface_id,
                authenticatedTenant,
              });

              return {
                content: [{
                  type: 'text',
                  text: JSON.stringify({
                    generated_content: genResult.content,
                    content_type: contentType,
                    governance_applied: genResult.governed,
                    decision: genResult.decision,
                    score: genResult.score,
                    modified: genResult.modified,
                    degraded_mode: genResult.degradedMode,
                    issues: genResult.issues,
                    gravito_run_id: genResult.gravito_run_id || `gen_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                    audit_trail: genResult.auditTrail,
                    product_registered: genResult.productRegistered,
                  }),
                }],
              };
            });
            break;
          }

          case 'gravito.toolHealth': {
            // Self-discovery endpoint for AI consumers
            // Returns which tools are functional, what schemas they expect, and which are stubs
            const category = args?.category; // optional filter: 'governance', 'messaging', 'experiments', 'operations', 'all'
            const includeSchemas = args?.includeSchemas !== false; // default true

            // Build health report from all tool sources
            const packTools = ALL_TOOLS.filter(t => !t.name.startsWith('gravito.') || BRIDGE_TOOL_SCHEMAS[t.name.replace('gravito.', '')]);

            // Categorize tools by function
            const toolCategories: Record<string, string[]> = {
              governance: ['reviewContent', 'governanceAudit', 'verifyClaim', 'checkCompliance', 'checkContentEnforcement', 'governedGenerate',
                'checkApprovedClaims', 'enforceDisclaimers', 'detectForbiddenLanguage', 'validateCitations', 'exportAuditTrail',
                'validateBusinessTruth', 'checkCriticalAlignment', 'analyzeCrossChannelCoherence', 'analyzeJourneyCoherence',
                'analyzePromiseProductAlignment', 'agentRuntimeValidateSite', 'detectDrift', 'registerApprovedClaim'],
              messaging: ['analyzePositioning', 'analyzeFearUrgency', 'checkSafeButForgettable', 'analyzeGravitas',
                'checkFeatureStartupLanguage', 'fullMessagingAnalysis', 'analyzeCompetitiveDifferentiation', 'checkGenericCopy',
                'analyzeBuyerObjections', 'checkCriticalObjectionGaps', 'comprehensiveGapAnalysis',
                'predictABTestWinner', 'quickABCompare', 'quickCompareHeadlines', 'compareMessaging',
                'getTrustRecommendations', 'getPreTractionMessaging'],
              creative: ['generateArtifact', 'generateVariants', 'experimentDesign', 'compareVariants', 'structureCreativity',
                'clarifyIntent', 'simulatePerception', 'detectAbstraction', 'checkCoherence', 'suggestRefinement', 'runCreativeIntegrity',
                'copilotGenerate', 'copilotRunPipeline', 'composeEmail'],
              experiments: ['reReview', 'recordFeedback', 'linkPatchToExperiment', 'recordOutcome', 'getPatchOutcome',
                'calculateAttribution', 'createExperimentFromPatch', 'evaluateExperimentOutcome', 'promoteWinner',
                'selectWinnerCandidate', 'createExperiment', 'publishPatch', 'autopilotCycle'],
              baselines: ['getLatestBaseline', 'getBaselineHistory', 'deactivateBaseline',
                'getAuditById', 'createAuditSchedule', 'updateAuditSchedule', 'deleteAuditSchedule', 'runScheduledAuditNow'],
              nexus: ['getNexusOverview', 'getSurfaceMap', 'getRiskHeatmap', 'getOutcomeLift'],
              operations: ['breakGlass', 'breakGlassDrill', 'runAutoExpire', 'runEscalation',
                'listBreakGlass', 'approveBreakGlass', 'revokeBreakGlass',
                'certifyRelease', 'exportReport', 'appealDecision', 'scheduleAudit'],
              financial: ['reviewTradingThesis', 'reviewTradeProposal', 'reviewStrategyChange', 'trackTradingOutcome'],
              safety: ['validateToolCall', 'detectPromptInjection', 'enforceEscalation', 'routeModel',
                'classifyClaims', 'requireEvidence', 'validateTruthSurface'],
              narrative_coherence: ['auditNarrativeCoherence', 'quickNarrativeCheck', 'discoverContentUnits', 'auditDocsCoherence'],
              content_digestibility: ['auditDigestibility', 'getDigestibilityHistory'],
            };

            // Determine tool health status
            type ToolHealthStatus = 'functional' | 'schema_override' | 'content_passthrough' | 'stub';
            const getToolHealth = (toolName: string): { status: ToolHealthStatus; schema: any | null } => {
              const shortName = toolName.replace('gravito.', '');
              const hasSchemaOverride = !!BRIDGE_TOOL_SCHEMAS[shortName];
              const hasCaseHandler = ALL_TOOLS.some(t => t.name === `gravito.${shortName}` && !t.name.includes('bridge'));

              // Tools with explicit case handlers are functional
              const explicitHandlers = [
                'reviewContent', 'governanceAudit', 'verifyClaim', 'composeEmail',
                'reviewTradingThesis', 'reviewTradeProposal', 'reviewStrategyChange', 'trackTradingOutcome',
                'checkCompliance', 'getDecisionTrace', 'generateArtifact', 'generateVariants',
                'experimentDesign', 'compareVariants', 'structureCreativity',
                'getNexusOverview', 'getSurfaceMap', 'recordOutcome', 'getRiskHeatmap', 'getOutcomeLift',
                'getCapabilities', 'checkApprovedClaims', 'enforceDisclaimers', 'detectForbiddenLanguage',
                'validateCitations', 'exportAuditTrail', 'reviewSequence', 'checkPersonalization',
                'enforceBrandVoice', 'trackReplyRate', 'validateToolCall', 'detectPromptInjection',
                'enforceEscalation', 'routeModel', 'classifyClaims', 'requireEvidence', 'validateTruthSurface',
                'clarifyIntent', 'simulatePerception', 'detectAbstraction', 'checkCoherence',
                'suggestRefinement', 'runCreativeIntegrity', 'selectWinnerCandidate', 'createExperiment',
                'publishPatch', 'autopilotCycle', 'certifyRelease', 'exportReport', 'appealDecision',
                'scheduleAudit', 'approveBreakGlass', 'revokeBreakGlass',
                'checkContentEnforcement', 'governedGenerate',
                'auditNarrativeCoherence', 'quickNarrativeCheck', 'discoverContentUnits', 'auditDocsCoherence',
                'auditDigestibility', 'getDigestibilityHistory',
              ];

              const schema = hasSchemaOverride ? BRIDGE_TOOL_SCHEMAS[shortName].inputSchema : null;

              if (explicitHandlers.includes(shortName)) {
                return { status: 'functional', schema };
              }
              if (hasSchemaOverride) {
                return { status: 'schema_override', schema };
              }
              // Bridge tools that accept content:string passthrough
              return { status: 'content_passthrough', schema: { type: 'object', properties: { content: { type: 'string' } }, required: ['content'] } };
            };

            // Build the report
            const filterCategory = category && category !== 'all' ? category : null;
            const report: any = {
              version: '1.0.0',
              timestamp: new Date().toISOString(),
              total_tools: ALL_TOOLS.length,
              summary: {
                functional: 0,
                schema_override: 0,
                content_passthrough: 0,
              },
              categories: {} as unknown as Record<string, unknown>,
            };

            for (const [cat, toolNames] of Object.entries(toolCategories)) {
              if (filterCategory && cat !== filterCategory) continue;
              const tools = toolNames.map(name => {
                const health = getToolHealth(name);
                report.summary[health.status] = (report.summary[health.status] || 0) + 1;
                return {
                  name: `gravito.${name}`,
                  status: health.status,
                  ...(includeSchemas && health.schema ? { inputSchema: health.schema } : {}),
                  description: BRIDGE_TOOL_SCHEMAS[name]?.description || ALL_TOOLS.find(t => t.name === `gravito.${name}`)?.description || '',
                };
              });
              report.categories[cat] = { count: tools.length, tools };
            }

            // Add uncategorized bridge tools
            if (!filterCategory) {
              const allCategorized = Object.values(toolCategories).flat();
              const uncategorized = ALL_TOOLS
                .filter(t => !allCategorized.includes(t.name.replace('gravito.', '')))
                .map(t => ({
                  name: t.name,
                  status: getToolHealth(t.name).status,
                  description: t.description || '',
                }));
              report.categories.other = { count: uncategorized.length, tools: uncategorized.slice(0, 20), total_uncategorized: uncategorized.length };
            }

            report.usage_guide = {
              functional: 'These tools have explicit handlers and work reliably. Call them with the documented schema.',
              schema_override: 'These tools route through the bridge but have correct schemas. Call them with the documented parameters.',
              content_passthrough: 'These tools accept a content:string field and route through the reviewer tRPC router. Most work with just { content: "your text" }.',
              recommendation: 'Start with governance and messaging tools for content review. Use toolHealth with category filter to explore specific areas.',
            };

            result = { content: [{ type: 'text', text: JSON.stringify(report, null, 2) }] };
            break;
          }

          // ============================================================
          // NARRATIVE COHERENCE TOOLS
          // ============================================================
          case 'gravito.auditNarrativeCoherence': {
            result = await safeTool(async () => {
              const surface = normalizedArgs?.surface || 'website';
              let auditResult;
              if (surface === 'docs' && normalizedArgs?.docsDir) {
                auditResult = await auditDocsDirectory(normalizedArgs.docsDir, normalizedArgs.surface);
              } else if (surface === 'generic' && normalizedArgs?.contentUnits) {
                const adapter = new GenericAdapter(normalizedArgs.contentUnits as ContentUnit[], 'generic');
                const { runNarrativeCoherenceAudit } = await import('../governance/narrative-coherence');
                auditResult = await runNarrativeCoherenceAudit(adapter);
              } else if (normalizedArgs?.routes?.length) {
                auditResult = await auditWebsiteRoutes(normalizedArgs.routes);
              } else {
                auditResult = await auditGravitoWebsite();
              }
              return { content: [{ type: 'text', text: JSON.stringify(auditResult) }] };
            });
            break;
          }

          case 'gravito.quickNarrativeCheck': {
            result = await safeTool(async () => {
              const surface = normalizedArgs?.surface || 'website';
              let adapter;
              if (surface === 'docs' && normalizedArgs?.docsDir) {
                adapter = new DocsAdapter(normalizedArgs.docsDir);
              } else {
                adapter = new WebsiteAdapter();
              }
              const checkResult = await quickCoherenceCheck(adapter);
              return { content: [{ type: 'text', text: JSON.stringify(checkResult) }] };
            });
            break;
          }

          case 'gravito.discoverContentUnits': {
            result = await safeTool(async () => {
              const surface = normalizedArgs?.surface || 'website';
              let adapter;
              if (surface === 'docs' && normalizedArgs?.docsDir) {
                adapter = new DocsAdapter(normalizedArgs.docsDir);
              } else {
                adapter = new WebsiteAdapter();
              }
              const units = adapter.discover();
              return { content: [{ type: 'text', text: JSON.stringify({ surface: adapter.surface, count: units.length, units }) }] };
            });
            break;
          }

          case 'gravito.auditDocsCoherence': {
            result = await safeTool(async () => {
              if (!normalizedArgs?.docsDir) {
                return { content: [{ type: 'text', text: JSON.stringify({ error: 'docsDir parameter is required' }) }] };
              }
              const auditResult = await auditDocsDirectory(normalizedArgs.docsDir, normalizedArgs.surface);
              return { content: [{ type: 'text', text: JSON.stringify(auditResult) }] };
            });
            break;
          }

          // ============================================================
          // CONTENT DIGESTIBILITY TOOLS
          // ============================================================
          case 'gravito.auditDigestibility': {
            result = await safeTool(async () => {
              const surface = normalizedArgs?.surface || 'website';
              let auditResult;
              if (surface === 'docs' && normalizedArgs?.docsDir) {
                const adapter = new DocsAdapter(normalizedArgs.docsDir);
                auditResult = await runDigestibilityAudit(adapter);
              } else if (surface === 'generic' && normalizedArgs?.contentUnits) {
                const { GenericAdapter: GA } = await import('../governance/narrative-coherence');
                const adapter = new GA(normalizedArgs.contentUnits as ContentUnit[], 'generic');
                auditResult = await runDigestibilityAudit(adapter);
              } else {
                auditResult = await auditGravitoDigestibility();
              }
              // Persist audit result to history table
              await recordDigestibilitySnapshot(auditResult, 'mcp');
              return { content: [{ type: 'text', text: JSON.stringify(auditResult) }] };
            });
            break;
          }

          case 'gravito.getDigestibilityHistory': {
            result = await safeTool(async () => {
              const latest = getLatestDigestibilityAudit();
              const history = getDigestibilityHistory();
              return { content: [{ type: 'text', text: JSON.stringify({ latest, history_count: history.length, history }) }] };
            });
            break;
          }

          case 'gravito.getContentIntelligence': {
            result = await safeTool(async () => {
              const report = await calculateContentIntelligence();
              return { content: [{ type: 'text', text: JSON.stringify(report) }] };
            });
            break;
          }

          case 'gravito.runContentIntelligenceAudit': {
            result = await safeTool(async () => {
              const report = await runFullContentIntelligenceAudit();
              return { content: [{ type: 'text', text: JSON.stringify(report) }] };
            });
            break;
          }

          case 'gravito.detectStructuralAntiPatterns': {
            result = await safeTool(async () => {
              const { WebsiteAdapter } = await import('../governance/narrative-coherence');
              const adapter = new WebsiteAdapter();
              const units = adapter.discover();
              const allPatterns: import('../governance/content-digestibility').StructuralAntiPattern[] = [];
              for (const unit of units) {
                allPatterns.push(...detectStructuralAntiPatterns(unit));
              }
              const byType: Record<string, number> = {};
              for (const p of allPatterns) {
                byType[p.pattern] = (byType[p.pattern] || 0) + 1;
              }
              return {
                content: [{
                  type: 'text',
                  text: JSON.stringify({
                    total_patterns: allPatterns.length,
                    by_type: byType,
                    patterns: allPatterns,
                  }),
                }],
              };
            });
            break;
          }

          // ============================================================
          // DEPLOYMENT TOOLS (8 tools for autonomous deployment)
          // ============================================================
          case 'deploy_content': {
            const { handleDeployContent } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleDeployContent(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'rollback_deployment': {
            const { handleRollbackDeployment } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleRollbackDeployment(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'scan_deployment': {
            const { handleScanDeployment } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleScanDeployment(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'promote_experiment': {
            const { handlePromoteExperiment } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handlePromoteExperiment(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'auto_remediate': {
            const { handleAutoRemediate } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleAutoRemediate(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'list_deployments': {
            const { handleListDeployments } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleListDeployments(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'get_deployment_status': {
            const { handleGetDeploymentStatus } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleGetDeploymentStatus();
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }
          case 'get_scan_results': {
            const { handleGetScanResults } = await import('../deployment/mcp-deployment-tools');
            result = await safeTool(async () => {
              const r = await handleGetScanResults(normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(r) }] };
            });
            break;
          }

          default: {
            // Bridge fallback - route to unified tool bridge for all other tools
            result = await safeTool(async () => {
              const bridge = getUnifiedToolBridge();
              const toolName = name?.replace('gravito.', '') || name;
              const bridgeResult = await bridge.invokeTool(toolName, normalizedArgs || {});
              return { content: [{ type: 'text', text: JSON.stringify(bridgeResult) }] };
            });
          }
        }
      }
        break;

      default:
        return res.json({
          jsonrpc: '2.0',
          id,
          error: { code: -32601, message: `Method not found: ${method}` },
        });
    }

    // Log successful request
    const toolName = method === 'tools/call' ? (params?.name || 'unknown') : method;
    const responseText = JSON.stringify(result);
    logUsage({
      apiKey,
      ipAddress: clientIp,
      toolName,
      method: method || 'unknown',
      success: true,
      responseTimeMs: Date.now() - requestStart,
      estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
      estimatedOutputTokens: estimateTokens(responseText),
      userAgent,
    });

    // Emit real-time governance event
    const isBlocked = responseText.includes('"block_release":true') || responseText.includes('"blocked":true');
    const scoreMatch = responseText.match(/"score"\s*:\s*(\d+)/);
    emitGovernanceEvent({
      type: isBlocked ? 'block' : 'approval',
      source: 'mcp',
      tool: toolName,
      score: scoreMatch ? parseInt(scoreMatch[1]) : undefined,
      blocked: isBlocked,
      details: `${toolName} via MCP`,
      apiKeyPrefix: apiKey?.substring(0, 12),
      durationMs: Date.now() - requestStart,
    });

    // ================================================================
    // GOVERNED USAGE METERING — increment monthly counter for billing
    // Only for tools/call (actual governance checks), not tools/list
    // ================================================================
    if (method === 'tools/call') {
      const authUserId = (req as McpAuthenticatedRequest).authUserId;
      // Fire-and-forget: don't block the response on metering
      (async () => {
        try {
          let stripeCustomerId: string | undefined;
          let stripeSubscriptionId: string | undefined;
          let plan: string | undefined;
          if (authUserId) {
            const sub = await getSubscriptionByUserId(authUserId);
            if (sub) {
              stripeCustomerId = sub.stripeCustomerId || undefined;
              stripeSubscriptionId = sub.stripeSubscriptionId || undefined;
              plan = sub.plan || undefined;
            }
          }
          await recordGovernedCheck({
            apiKeyPrefix: apiKey?.substring(0, 16),
            userId: authUserId,
            stripeCustomerId,
            stripeSubscriptionId,
            plan,
            toolName,
            success: true,
            blocked: isBlocked,
            responseTimeMs: Date.now() - requestStart,
            estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
            estimatedOutputTokens: estimateTokens(responseText),
            ipAddress: clientIp,
            userAgent,
          });
        } catch (meterErr) {
          generalLog.error('[MCP] Usage metering error (non-fatal):', meterErr);
        }
      })();
    }

    // Record latency for Prometheus metrics
    recordLatencyObservation('request', Date.now() - requestStart);
    res.json({ jsonrpc: '2.0', id, result });

  } catch (error) {
    generalLog.error('[MCP JSON-RPC] Error:', error);

    // Log failed request
    const toolName = req.body?.method === 'tools/call' ? (req.body?.params?.name || 'unknown') : (req.body?.method || 'unknown');
    logUsage({
      apiKey,
      ipAddress: clientIp,
      toolName,
      method: req.body?.method || 'unknown',
      success: false,
      errorMessage: error instanceof Error ? error.message : 'Internal error',
      responseTimeMs: Date.now() - requestStart,
      userAgent,
    });

    // Emit error event
    emitGovernanceEvent({
      type: 'error',
      source: 'mcp',
      tool: toolName,
      details: error instanceof Error ? error.message : 'Internal error',
      apiKeyPrefix: apiKey?.substring(0, 12),
      durationMs: Date.now() - requestStart,
    });

    // NEVER expose raw error.message to customer — use generic message only
    res.json({
      jsonrpc: '2.0',
      id: req.body?.id,
      error: { code: -32603, message: 'Request could not be processed — please retry or contact support' },
    });
  }
});

// ============================================================================
// HEALTH CHECK (Unauthenticated - includes auth metadata)
// ============================================================================

mcpRouter.get('/health', (req: Request, res: Response) => {
  ensureServerInitialized();
  const server = getGravitoMCPServer();

  // Collect circuit breaker metrics
  const cbMetrics = getAllCircuitBreakerMetrics();
  const openBreakers = cbMetrics.filter(m => m.state === 'OPEN');
  const halfOpenBreakers = cbMetrics.filter(m => m.state === 'HALF_OPEN');
  const totalCalls = cbMetrics.reduce((sum, m) => sum + m.totalCalls, 0);
  const totalFallbacks = cbMetrics.reduce((sum, m) => sum + m.fallbacksUsed, 0);
  const fallbackRate = totalCalls > 0 ? Math.round((totalFallbacks / totalCalls) * 10000) / 100 : 0;

  // Determine overall status
  // degraded: any circuit breaker is OPEN or fallback rate > 10%
  // down: all circuit breakers are OPEN
  const allOpen = cbMetrics.length > 0 && cbMetrics.every(m => m.state === 'OPEN');
  const anyOpen = openBreakers.length > 0;
  const status = allOpen ? 'down' : (anyOpen || fallbackRate > 10) ? 'degraded' : 'ok';

  res.json({
    name: GRAVITO_MCP_SERVER_NAME,
    transport: 'http',
    status,
    tools_count: ALL_TOOLS.length,
    // Explicitly declare auth type (NOT OAuth) - critical for Manus
    auth: {
      type: 'api_key',
      in: 'header',
      header: 'Authorization',
      format: 'Bearer <token>',
      oauth: false,
      requires_login: false,
    },
    // Operational health
    circuitBreakers: {
      total: cbMetrics.length,
      open: openBreakers.length,
      halfOpen: halfOpenBreakers.length,
      closed: cbMetrics.length - openBreakers.length - halfOpenBreakers.length,
      openNames: openBreakers.map(m => m.name),
    },
    fallbackRate: `${fallbackRate}%`,
    regulatedFailClosed: true, // Always true — regulated surfaces never degrade
    retryPolicy: {
      maxAttempts: 3,
      backoffMs: [1000, 2000, 4000],
      retryableErrors: ['external_authority_unavailable', 'upstream_timeout', 'degraded_mode'],
    },
    timestamp: new Date().toISOString(),
  });
});

// ============================================================================
// AUTH ENDPOINT (Explicit auth declaration for Manus)
// ============================================================================

mcpRouter.get('/auth', (req: Request, res: Response) => {
  // Explicit auth declaration endpoint - Manus can query this to determine auth type
  res.json({
    auth: {
      type: 'api_key',
      in: 'header',
      header: 'Authorization',
      format: 'Bearer <token>',
      oauth: false,
    },
  });
});

// ============================================================================
// LIST TOOLS (Unauthenticated for Manus discovery - prevents OAuth inference)
// ============================================================================

mcpRouter.post('/tools/list', (req: Request, res: Response) => {
  ensureServerInitialized();

  // Convert Zod schemas to JSON Schema format for MCP compatibility
  // Finance Pack tools already have JSON schema, others need conversion
  const catalog = resolveToolsForMcpList();
  const tools = catalog.map(tool => {
    // Check if inputSchema is already a plain object (JSON schema) vs Zod schema
    const schema = tool.inputSchema;
    return {
      name: tool.name,
      description: tool.description,
      inputSchema: isZodSchema(schema) ? zodToJsonSchema(schema) : schema,
    };
  });

  res.json({
    tools,
    tool_pack: process.env.MCP_TOOL_PACK?.trim() || 'all',
    server_name: GRAVITO_MCP_SERVER_NAME,
    version: '1.0.0',
    // Explicitly declare auth type (NOT OAuth)
    auth: AUTH_METADATA,
  });
});


// ============================================================================
// HELPER: Convert Zod schema to JSON Schema
// ============================================================================

/** A JSON Schema node as emitted by the converter below. */
interface JsonSchemaNode {
  type: string;
  description?: string;
  enum?: (string | number)[];
  properties?: Record<string, JsonSchemaNode>;
  required?: string[];
  items?: JsonSchemaNode;
  default?: unknown;
}

/**
 * The slice of a Zod schema's internal `_def` that the converter reads.
 * Zod 4 tags the kind on `type` and keeps enum members on `entries`; schemas
 * built by Zod 3 tag the kind on `typeName`, keep enum members on `values`
 * and store an array's element schema on `type`. Both layouts are probed, so
 * every field is optional and `type` carries either tag or element schema.
 */
interface ZodDefProbe {
  type?: string | z.ZodType<unknown>;
  typeName?: string;
  entries?: Record<string, string | number>;
  values?: (string | number)[] | Record<string, string | number>;
  element?: z.ZodType<unknown>;
  innerType?: z.ZodType<unknown>;
  defaultValue?: unknown;
}

/** True when a tool's `inputSchema` is a Zod schema rather than a literal JSON Schema. */
function isZodSchema(value: unknown): value is z.ZodType<unknown> {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as { parse?: unknown; _def?: unknown };
  return typeof candidate.parse === 'function' && typeof candidate._def === 'object';
}

/** Read the internal definition of a Zod schema through the probe above. */
function readZodDef(schema: z.ZodType<unknown>): ZodDefProbe {
  const def: unknown = schema._def;
  return typeof def === 'object' && def !== null ? (def as ZodDefProbe) : {};
}

/** Normalise Zod's enum members: a list in Zod 3, the enum object for native enums. */
function readEnumValues(values: ZodDefProbe['values']): (string | number)[] | undefined {
  if (Array.isArray(values)) return values;
  if (typeof values === 'object' && values !== null) return Object.values(values);
  return undefined;
}

function zodToJsonSchema(schema: z.ZodType<unknown>, definitions?: Map<string, JsonSchemaNode>): JsonSchemaNode {
  // Basic conversion - for full compatibility, use zod-to-json-schema package
  const description = schema.description || '';
  const def = readZodDef(schema);

  // Check for enum using multiple detection methods
  // Zod 3.x uses _def.type === 'enum' and _def.entries
  if (def.type === 'enum' && def.entries) {
    return {
      type: 'string',
      enum: Object.keys(def.entries),
      description,
    };
  }

  // Zod 3.x alternative: check typeName
  if (def.typeName === 'ZodEnum') {
    return {
      type: 'string',
      enum: readEnumValues(def.values) ?? Object.keys(def.entries || {}),
      description,
    };
  }

  if (def.typeName === 'ZodNativeEnum') {
    return {
      type: 'string',
      enum: readEnumValues(def.values) ?? [],
      description,
    };
  }

  if (schema instanceof z.ZodObject) {
    const shape: Record<string, unknown> = schema.shape;
    const properties: Record<string, JsonSchemaNode> = {};
    const required: string[] = [];

    for (const [key, value] of Object.entries(shape)) {
      const field = isZodSchema(value) ? value : undefined;
      properties[key] = field ? zodToJsonSchema(field, definitions) : { type: 'any', description: '' };
      if (!field?.isOptional()) {
        required.push(key);
      }
    }

    return {
      type: 'object',
      properties,
      required: required.length > 0 ? required : undefined,
      description,
    };
  }

  if (schema instanceof z.ZodString) {
    return { type: 'string', description };
  }

  if (schema instanceof z.ZodNumber) {
    return { type: 'number', description };
  }

  if (schema instanceof z.ZodBoolean) {
    return { type: 'boolean', description };
  }

  if (schema instanceof z.ZodArray) {
    // Zod 4 keeps the element schema on `element`, Zod 3 on `type`.
    const element = def.element ?? def.type;
    return {
      type: 'array',
      items: isZodSchema(element) ? zodToJsonSchema(element, definitions) : { type: 'any', description: '' },
      description,
    };
  }

  // ZodEnum already handled above via typeName check
  if (schema instanceof z.ZodEnum) {
    return {
      type: 'string',
      enum: readEnumValues(def.values) ?? Object.keys(def.entries || {}),
      description,
    };
  }

  if (schema instanceof z.ZodDefault) {
    const inner: JsonSchemaNode = isZodSchema(def.innerType)
      ? zodToJsonSchema(def.innerType, definitions)
      : { type: 'any', description };
    try {
      const defaultVal = def.defaultValue;
      inner.default = typeof defaultVal === 'function' ? defaultVal() : defaultVal;
    } catch {
      // Ignore default value extraction errors
    }
    return inner;
  }

  if (schema instanceof z.ZodOptional) {
    return zodToJsonSchema(def.innerType ?? schema.unwrap(), definitions);
  }

  // Fallback
  return { type: 'any', description };
}

// ============================================================================
// USAGE STATS ENDPOINT (Authenticated - for dashboard/billing)
// ============================================================================

mcpRouter.get('/usage', authenticateMCP, async (req: Request, res: Response) => {
  try {
    const period = (req.query.period as string) || '24h';
    const since = new Date();
    switch (period) {
      case '1h': since.setHours(since.getHours() - 1); break;
      case '24h': since.setHours(since.getHours() - 24); break;
      case '7d': since.setDate(since.getDate() - 7); break;
      case '30d': since.setDate(since.getDate() - 30); break;
      default: since.setHours(since.getHours() - 24);
    }

    const stats = await getUsageStats(since);
    res.json({
      period,
      since: since.toISOString(),
      ...stats,
    });
  } catch (error) {
    generalLog.error('[MCP Usage] Error:', error);
    res.status(500).json({ error: 'Failed to retrieve usage stats' });
  }
});

// ============================================================================
// EXPORT DEFAULT ROUTER
// ============================================================================

export default mcpRouter;

